const $ = (s,root=document)=>root.querySelector(s); const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const role=document.body.dataset.role||'customer'; const page=document.body.dataset.page||'dashboard';
const notifiedReadyOrders=new Set();
const kitchenSoundPreferenceKey='restaurantos:kitchen-notification-sound';
const waiterSoundPreferenceKey='restaurantos:waiter-notification-sound';
const kitchenNotificationAudio=new Audio('/assets/notification.mp3');
kitchenNotificationAudio.preload='auto';
let kitchenSoundEnabled=true,kitchenInitialOrdersLoaded=false,kitchenSoundPlaybackWarningShown=false;
let waiterSoundEnabled=false,waiterSoundPlaybackWarningShown=false;
const knownKitchenOrderIds=new Set();
try{kitchenSoundEnabled=localStorage.getItem(kitchenSoundPreferenceKey)!=='off'}catch(error){console.warn('Could not read kitchen sound preference.',error)}
try{waiterSoundEnabled=localStorage.getItem(waiterSoundPreferenceKey)==='on'}catch(error){console.warn('Could not read waiter sound preference.',error)}
let socket=null, authenticatedAccount=null, csrfToken='', config={restaurant:'Maison Table',currency:'INR',taxRate:5,origin:location.origin}, menu=[], tables=[], orders=[], selectedTable=Number(new URLSearchParams(location.search).get('table'))||1, cart={}, sessionData=null;
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:config.currency||'INR',maximumFractionDigits:2}).format(Number(n||0));
window.addEventListener('pageshow',()=>{if(role==='customer'&&page==='menu'){const completedAt=Number(sessionStorage.getItem('restaurantos:payment-complete-at')||0);if(completedAt&&Date.now()-completedAt<30*60*1000){const table=Number(new URLSearchParams(location.search).get('table'))||1;location.replace('/review/index.html?table='+table+'&session='+(sessionStorage.getItem('restaurantos:paid-session')||''));}}});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(url,options={}){const headers={'Content-Type':'application/json',...(csrfToken?{'X-CSRF-Token':csrfToken}:{}),...(options.headers||{})};const res=await fetch(url,{...options,credentials:'same-origin',headers});const data=await res.json().catch(()=>({error:'Invalid server response'}));if(!res.ok){const error=new Error(data.error||`Request failed (${res.status})`);error.status=res.status;throw error}return data}
async function billingQrDataUrl(billId){const res=await fetch(`/api/billing/qr/${encodeURIComponent(billId)}`,{credentials:'same-origin'});if(!res.ok){const data=await res.json().catch(()=>({}));throw new Error(data.error||`Could not load payment QR (${res.status}).`)}const blob=await res.blob();return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read payment QR code.'));reader.readAsDataURL(blob)})}
function toast(message,bad=false){const n=document.createElement('div');n.className='toast'+(bad?' bad':'');n.textContent=message;document.body.append(n);setTimeout(()=>n.remove(),3500)}
function setNotice(message,bad=false){const n=$('#notice');if(!n)return;n.textContent=message;n.className=bad?'error':'notice';n.classList.remove('hidden')}
function shellNav(){const navMap={owner:[['Dashboard','/owner/index.html','⌂'],['Tables & QR','/owner/tables.html','▦'],['Menu manager','/owner/menu.html','☷'],['Billing counter','/owner/billing.html','₹'],['Payments','/owner/payments.html','▤'],['Settings','/owner/settings.html','⚙'],['Reports','/owner/reports.html','↗']],waiter:[['Floor overview','/waiter/index.html','⌂'],['Ready to serve','/waiter/ready.html','🔔'],['Create order','/waiter/order.html','＋'],['Table sessions','/waiter/tables.html','▦']],kitchen:[['Kitchen display','/kitchen/index.html','▤'],['Completed tickets','/kitchen/history.html','✓']], 'super-admin':[['Technical health','/super-admin/index.html','⌁'],['Broadcasts','/super-admin/broadcasts.html','↗'],['System events','/super-admin/events.html','≋']]};const labels={owner:'Restaurant owner',waiter:'Floor & service',kitchen:'Kitchen operations','super-admin':'Technical admin'};const links=navMap[role]||[];const current=location.pathname;return `<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-mark">R</span><span>RestaurantOS<small>${labels[role]||'Guest ordering'}</small></span></div><div><div class="nav-label">Workspace</div><nav class="nav">${links.map(([label,href,icon])=>`<a class="${current===href?'active':''}" href="${href}"><span>${icon}</span>${label}</a>`).join('')}</nav></div><div class="side-bottom"><div><span class="live-dot"></span><span id="connection-label">Connecting live updates…</span></div><p style="margin:10px 0 13px;line-height:1.6">One restaurant. One shared live workspace.</p></aside><main class="main"><header class="topbar"><div class="topbar-left"><button class="btn mobile-menu" id="mobile-menu">☰</button><div><div class="eyebrow">${esc(config.restaurant)} · Workspace</div><div class="page-title">${document.body.dataset.title||'Overview'}</div></div></div><div class="topbar-left"><span class="pill green"><span class="live-dot" style="margin:0"></span> Live</span><button class="btn btn-sm" id="account-menu">${esc(authenticatedAccount?.username||'Account')} · Sign out</button><div class="avatar">${role==='owner'?'OW':role==='waiter'?'FL':role==='kitchen'?'KT':'SA'}</div></div></header><section class="content" id="content">${$('#content')?.innerHTML||''}</section></main></div>`}
function setupShell(){if(document.body.dataset.layout==='customer')return;const bodyContent=$('#content')?.innerHTML||'';document.body.innerHTML=shellNav();$('#content').innerHTML=bodyContent;$('#mobile-menu')?.addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#account-menu')?.addEventListener('click',showAccountDialog)}
function connectSocket(){if(typeof io==='undefined')return;socket=io();socket.on('connect',()=>{const el=$('#connection-label');if(el)el.textContent='Connected · live sync on';$$('.pill.green').forEach(x=>x.title='Live connection active')});socket.on('disconnect',()=>{const el=$('#connection-label');if(el)el.textContent='Reconnecting…'});for(const event of ['orders:updated','tables:updated','menu:updated','billing:updated'])socket.on(event,()=>refreshCurrent());socket.on('billing:updated',payload=>{if(role==='customer'&&['status','menu'].includes(page)&&Number(payload?.tableId)===Number(selectedTable)&&payload?.status==='paid')redirectToReview(payload.tableId,payload.sessionId)});socket.on('orders:updated',async payload=>{if(role!=='waiter'||!payload?.orderId)return;try{const ready=await api('/api/orders?status=ready');const order=ready.find(o=>Number(o.id)===Number(payload.orderId));if(order&&!notifiedReadyOrders.has(Number(order.id))){notifiedReadyOrders.add(Number(order.id));toast(`🔔 Order ready for pickup — deliver to ${order.table_name} (Ticket #${order.id})`);playWaiterNotification();if('vibrate'in navigator)navigator.vibrate([180,80,180]);}}catch(e){console.debug('Could not check ready-order notification',e)}});}
async function init(){if(role!=='customer'){try{const result=await api('/api/auth/me');authenticatedAccount=result.account;csrfToken=result.account.csrfToken;if(authenticatedAccount.role!==role){location.replace(accountHome(authenticatedAccount.role));return}if(authenticatedAccount.mustChangePassword){renderCredentialScreen(true);return}}catch(error){if(error.status!==401){document.body.innerHTML=`<main class="auth-screen"><section class="panel"><h1>Unable to verify your sign-in</h1><p>${esc(error.message)}</p><button class="btn" onclick="location.reload()">Try again</button></section></main>`;return}renderLoginScreen();return}}else{try{const result=await api('/api/auth/me');csrfToken=result.account.csrfToken}catch(error){if(error.status!==401)console.error('Could not load optional staff session for customer page.',error)}}try{config=await api('/api/config');if(config.googleReviewUrl)window.RESTAURANT_GOOGLE_REVIEW_URL=config.googleReviewUrl;}catch{}; if(document.body.dataset.layout!=='customer')setupShell(); if(role==='owner')await initOwner(); else if(role==='waiter')await initWaiter(); else if(role==='kitchen')await initKitchen(); else if(role==='customer')await initCustomer(); else await initAdmin(); connectSocket();}
function accountHome(accountRole){return ({owner:'/owner/index.html',waiter:'/waiter/index.html',kitchen:'/kitchen/index.html','super-admin':'/super-admin/index.html'})[accountRole]||'/owner/index.html'}
function authScreen(content){document.body.innerHTML=`<main class="auth-screen" style="min-height:100vh;display:grid;place-items:center;padding:24px;background:#f4f7f4"><section class="panel" style="width:min(100%,460px);padding:28px">${content}</section></main>`}
function renderLoginScreen(error=''){authScreen(`<div class="eyebrow">RestaurantOS staff access</div><h1>Sign in</h1><p class="muted">Use your staff account to access this workspace.</p><form id="staff-login-form"><div class="field"><label>Username</label><input id="staff-username" autocomplete="username" required></div><div class="field"><label>Password</label><input id="staff-password" type="password" autocomplete="current-password" required></div><p id="auth-error" class="error">${esc(error)}</p><button class="btn btn-primary" type="submit">Sign in</button></form>`);$('#staff-login-form').onsubmit=async event=>{event.preventDefault();const button=$('button[type="submit"]',event.currentTarget);button.disabled=true;try{const result=await api('/api/auth/login',{method:'POST',body:JSON.stringify({username:$('#staff-username').value,password:$('#staff-password').value})});authenticatedAccount=result.account;csrfToken=result.account.csrfToken;if(result.account.mustChangePassword)renderCredentialScreen(true);else location.replace(accountHome(result.account.role))}catch(e){$('#auth-error').textContent=e.message;button.disabled=false}}}
function renderCredentialScreen(mandatory){const ownerNeedsUsername=authenticatedAccount.mustChangeUsername;authScreen(`<div class="eyebrow">Account security</div><h1>${ownerNeedsUsername?'Secure your owner account':'Change your password'}</h1><p class="muted">${ownerNeedsUsername?'Set a new owner username and password before continuing.':'Update your password to continue. Passwords must be at least 12 characters.'}</p><form id="credential-form"><div class="field"><label>Current password</label><input id="credential-current" type="password" autocomplete="current-password" required></div><div class="field"><label>${ownerNeedsUsername?'New username':'New username (optional)'}</label><input id="credential-username" autocomplete="username" ${ownerNeedsUsername?'required':''}></div><div class="field"><label>New password</label><input id="credential-password" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></div><div class="field"><label>Confirm new password</label><input id="credential-confirm" type="password" autocomplete="new-password" minlength="12" maxlength="256" required></div><p id="auth-error" class="error"></p><button class="btn btn-primary" type="submit">Save and continue</button></form>`);$('#credential-form').onsubmit=async event=>{event.preventDefault();if($('#credential-password').value!==$('#credential-confirm').value){$('#auth-error').textContent='New passwords do not match.';return}const button=$('button[type="submit"]',event.currentTarget);button.disabled=true;try{const result=await api('/api/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword:$('#credential-current').value,username:$('#credential-username').value,newPassword:$('#credential-password').value})});authenticatedAccount=result.account;csrfToken=result.account.csrfToken;toast('Account credentials updated.');location.replace(accountHome(result.account.role))}catch(e){$('#auth-error').textContent=e.message;button.disabled=false}}}
function showAccountDialog(){modal(`<h2>Account settings</h2><p class="muted small">Change your staff username or password. New passwords must be at least 12 characters.</p><div class="field"><label>Current password</label><input id="account-current-password" type="password" autocomplete="current-password"></div><div class="field"><label>New username (optional)</label><input id="account-new-username" value="${esc(authenticatedAccount.username)}" autocomplete="username"></div><div class="field"><label>New password</label><input id="account-new-password" type="password" minlength="12" maxlength="256" autocomplete="new-password"></div><div class="field"><label>Confirm new password</label><input id="account-confirm-password" type="password" minlength="12" maxlength="256" autocomplete="new-password"></div><p id="account-error" class="error"></p><div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn" id="save-account">Save changes</button><button class="btn btn-primary" id="sign-out">Sign out</button></div>`);$('#save-account').onclick=async()=>{const newPassword=$('#account-new-password').value;if(!newPassword){$('#account-error').textContent='Enter a new password.';return}if(newPassword!==$('#account-confirm-password').value){$('#account-error').textContent='New passwords do not match.';return}try{const result=await api('/api/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword:$('#account-current-password').value,username:$('#account-new-username').value,newPassword})});authenticatedAccount=result.account;csrfToken=result.account.csrfToken;location.reload()}catch(e){$('#account-error').textContent=e.message}};$('#sign-out').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST'});location.reload()}catch(e){$('#account-error').textContent=e.message}}}
async function refreshCurrent(){try{if(role==='owner'){if(page==='dashboard')await ownerDashboard();if(page==='tables')await ownerTables();if(page==='billing')await ownerBilling();if(page==='payments')await ownerPayments();if(page==='settings')await ownerSettings();if(page==='reports')await ownerReports();}if(role==='waiter'){if(page==='dashboard')await waiterDashboard();if(page==='order')await waiterOrder();if(page==='tables')await waiterTables();if(page==='ready')await waiterReady();}if(role==='kitchen'){if(page==='kitchen')await kitchenBoard();if(page==='history')await kitchenHistory();}if(role==='customer'){if(page==='menu')await customerMenu(false);if(page==='status')await customerStatus();}}catch(e){console.error(e)}}
function stat(label,value,foot,icon){return `<div class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
function statusPill(status){const c={new:'orange',preparing:'blue',ready:'green',served:'green',cancelled:'red',pending:'orange',partial:'blue',paid:'green',open:'green',closed:''};return `<span class="pill ${c[status]||''}">${esc(status||'pending')}</span>`}
async function initOwner(){if(page==='dashboard')await ownerDashboard();if(page==='tables')await ownerTables();if(page==='menu')await ownerMenu();if(page==='billing')await ownerBilling();if(page==='payments')await ownerPayments();if(page==='settings')await ownerSettings();if(page==='reports')await ownerReports();}
async function ownerDashboard(){const s=await api('/api/owner/summary');const t=await api('/api/tables');$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">Today at a glance</div><h1>Good service starts here.</h1><div class="muted small">Monitor tables, orders and collections from one place.</div></div><a class="btn btn-primary" href="/owner/billing.html">Open billing counter ↗</a></div><div class="stats">${stat('Active tables',s.openSessions,`${s.tables} tables configured`,'▦')}${stat('Orders today',s.todayOrders,'Across active service','≋')}${stat('Collections today',money(s.todayCollections),'Recorded payments only','₹')}${stat('Pending bills',s.pendingBills,'Need cashier attention','◷')}</div><div class="panel"><div class="panel-head"><h2>Live table overview</h2><a class="btn btn-sm" href="/owner/tables.html">Manage tables →</a></div><div class="table-grid">${t.filter(x=>!x.isPickup).map(tableCard).join('')}</div></div>`}
function tableCard(t){return `<article class="table-card"><div class="table-card-top"><div class="table-number">${esc(t.name)}</div>${t.occupied?'<span class="pill orange">Occupied</span>':'<span class="pill green">Available</span>'}</div><div class="muted small" style="margin-top:8px">Seats ${t.capacity} · ${t.orderCount} order(s)</div><div class="amount">${money(t.estimatedTotal)}</div><div class="muted small">Estimated session total</div><div class="table-card-foot"><span class="small">${t.billStatus==='paid'?'Paid':t.occupied?'Open session':'Ready for guests'}</span><a class="btn btn-sm" href="/owner/billing.html?table=${t.id}">Bill / view</a></div></article>`}

async function ownerTables(){
  tables=await api('/api/tables');
  const regularTables = tables.filter(t=>!t.isPickup);
  $('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">Floor plan</div><h1>Tables & QR codes</h1><div class="muted small">Create tables, preview printable QR codes and open a customer menu for each table.</div></div><button class="btn btn-primary" id="add-table">＋ Add new table</button></div><div class="panel" style="margin-bottom:20px"><div class="panel-head"><h2>🛍️ Pickup Counter QR code</h2><span class="muted small">Separate customer ordering station for takeouts</span></div><div class="table-grid"><article class="table-card"><div class="table-card-top"><div class="table-number">Pickup Orders</div><span class="pill green">Active QR</span></div><div class="muted small" style="margin-top:8px">Counter takeout station</div><div class="amount">🛍️</div><div class="muted small">Customer pickup flow</div><div class="table-card-foot"><button class="btn btn-sm" id="preview-pickup-qr">▦ Preview QR</button><a class="btn btn-sm" target="_blank" href="/customer/pickup.html">Open pickup flow ↗</a></div></article></div></div><div class="panel"><div class="panel-head"><h2>Restaurant tables <span class="pill">${regularTables.length}</span></h2><span class="muted small">QR target uses the server's LAN IP</span></div><div class="table-grid">${regularTables.map(t=>`<article class="table-card"><div class="table-card-top"><div class="table-number">${esc(t.name)}</div>${t.occupied?'<span class="pill orange">Occupied</span>':'<span class="pill green">Available</span>'}</div><div class="muted small" style="margin-top:8px">Capacity · ${t.capacity} guests</div><div class="amount">${t.occupied?money(t.estimatedTotal):'—'}</div><div class="muted small">${t.occupied?'Current estimated bill':'No active session'}</div><div class="table-card-foot"><button class="btn btn-sm" data-qr="${t.id}">▦ Preview QR</button><a class="btn btn-sm" target="_blank" href="/customer/menu.html?table=${t.id}">Open menu ↗</a></div></article>`).join('')}</div></div>`;
  
  $('#add-table').onclick = () => {
    modal(`<h2>Add a restaurant table</h2><div class="field"><label>Table name</label><input id="new-table-name" placeholder="e.g. Patio 09" required></div><div class="field"><label>Seating capacity</label><input id="new-table-capacity" type="number" min="1" max="20" value="4"></div><p class="muted small">A unique table is created in the shared database. You can preview and print its QR immediately.</p><div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn btn-primary" id="save-table">Create table</button></div>`);
    $('#save-table').onclick = async () => {
      try {
        const t = await api('/api/tables',{method:'POST',body:JSON.stringify({name:$('#new-table-name').value,capacity:$('#new-table-capacity').value})});
        closeModal(); await ownerTables(); showQR(t.id); toast('Table created successfully.');
      } catch(e) { toast(e.message, true) }
    };
  };
  $('#preview-pickup-qr').onclick = () => showPickupQR();
  $$('[data-qr]').forEach(b=>b.onclick=()=>showQR(b.dataset.qr));
}

function modal(html){$('#modal-root')?.remove();const wrap=document.createElement('div');wrap.id='modal-root';wrap.className='modal-backdrop';wrap.innerHTML=`<div class="modal">${html}</div>`;document.body.append(wrap);wrap.addEventListener('click',e=>{if(e.target===wrap||e.target.closest('[data-close]'))closeModal()})}function closeModal(){$('#modal-root')?.remove()}

async function showPickupQR(){
  const cfg = await api('/api/config'); const origin = cfg.origin;
  const target = `${origin}/customer/pickup.html`;
  const accessNote=cfg.publicUrlConfigured?'Customers can open this link over mobile internet when your public URL is routed to this server.':'This QR uses the café LAN address. Customers must be connected to the same Wi-Fi until a public URL is configured.';
  modal(`<h2>Pickup Counter QR</h2><div class="qr-preview"><img src="/api/pickup/qr.png" alt="Pickup QR code"><strong>Pickup Station</strong><span class="muted small" style="text-align:center;overflow-wrap:anywhere">${esc(target)}</span></div><p class="muted small">${accessNote}</p><div class="modal-actions"><button class="btn" data-close>Close</button><button class="btn" id="copy-pickup-url">Copy link</button><button class="btn btn-primary" id="print-pickup-qr-modal">Print QR</button></div>`);
  $('#copy-pickup-url').onclick = async () => { await navigator.clipboard.writeText(target); toast('Pickup link copied.'); };
  $('#print-pickup-qr-modal').onclick = () => {
    const w = window.open('/api/pickup/qr.png','_blank'); w?.addEventListener('load',()=>w.print());
  };
}

async function showQR(id){const t=tables.find(x=>x.id===Number(id))|| (await api('/api/tables')).find(x=>x.id===Number(id));const cfg=await api('/api/config');const origin=cfg.origin;const qrUrl=`/api/qr/${id}.png`;const target=`${origin}/customer/menu.html?table=${id}`;const accessNote=cfg.publicUrlConfigured?'Customers can open this link over mobile internet when your public URL is routed to this server.':'This QR uses the café LAN address. Customers must be connected to the same Wi-Fi until a public URL is configured.';modal(`<h2>Table QR · ${esc(t?.name||`Table ${id}`)}</h2><div class="qr-preview"><img src="${qrUrl}" alt="QR code for table ${id}"><strong>${esc(t?.name||'Table')}</strong><span class="muted small" style="text-align:center;overflow-wrap:anywhere">${esc(target)}</span></div><p class="muted small">${accessNote} Keep the server running while guests scan.</p><div class="modal-actions"><button class="btn" data-close>Close</button><button class="btn" id="copy-qr-url">Copy menu link</button><button class="btn btn-primary" id="print-qr">Print QR</button></div>`);$('#copy-qr-url').onclick=async()=>{await navigator.clipboard.writeText(target);toast('Table menu link copied.')};$('#print-qr').onclick=()=>{const img=$('.qr-preview img');const w=window.open('','_blank');w.document.write(`<html><head><title>QR ${esc(t?.name||'Table')}</title><style>body{font-family:Arial;text-align:center;padding:32px}img{width:340px}p{overflow-wrap:anywhere}</style></head><body><h1>${esc(config.restaurant)}</h1><h2>${esc(t?.name||'Table')}</h2><img src="${img.src}"><p>${esc(target)}</p><p>Scan to view menu and order</p><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}}

async function ownerMenu(){
  menu=await api('/api/menu/manage');
  $('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">Food & beverage</div><h1>Menu manager</h1><div class="muted small">Update prices and availability. Past order item snapshots remain unchanged.</div></div><button class="btn btn-primary" id="add-menu">＋ Add menu item</button></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Item</th><th>Category</th><th>Price</th><th>Availability</th><th>Action</th></tr></thead><tbody>${menu.map(m=>`<tr><td><div style="display:flex;align-items:center;gap:10px"><img src="${esc(m.image)}" style="width:48px;height:42px;object-fit:cover;border-radius:9px" onerror="this.style.display='none'"><div><strong>${esc(m.name)}</strong><div class="muted small">${esc(m.description)}</div></div></div></td><td>${esc(m.category)}</td><td><strong>${money(m.price)}</strong></td><td>${m.available?'<span class="pill green">Available</span>':'<span class="pill red">Unavailable</span>'}</td><td><button class="btn btn-sm" data-edit="${m.id}">Edit</button></td></tr>`).join('')}</tbody></table></div></div>`;
  const form=(m={})=>{
    modal(`<h2>${m.id?'Edit menu item':'Add menu item'}</h2><div class="field"><label>Dish name</label><input id="m-name" value="${esc(m.name||'')}" required></div><div class="form-grid"><div class="field"><label>Category</label><input id="m-category" value="${esc(m.category||'Mains')}" required></div><div class="field"><label>Price (₹)</label><input id="m-price" type="number" min="0" step="0.01" value="${m.price??''}" required></div></div><div class="field"><label>Description</label><textarea id="m-desc" rows="2">${esc(m.description||'')}</textarea></div><div class="field"><label>Unsplash image URL</label><input id="m-image" value="${esc(m.image||'')}" placeholder="https://images.unsplash.com/..."></div><div class="field"><label><input id="m-available" type="checkbox" ${m.available!==0?'checked':''} style="width:auto"> Available to order</label></div><div class="modal-actions"><button class="btn" data-close>Cancel</button><button class="btn btn-primary" id="save-menu">Save item</button></div>`);
    $('#save-menu').onclick=async()=>{const body={name:$('#m-name').value,category:$('#m-category').value,price:$('#m-price').value,description:$('#m-desc').value,image:$('#m-image').value,available:$('#m-available').checked};try{await api(m.id?`/api/menu/${m.id}`:'/api/menu',{method:m.id?'PATCH':'POST',body:JSON.stringify(body)});closeModal();await ownerMenu();toast('Menu saved.')}catch(e){toast(e.message,true)}};
  };
  $('#add-menu').onclick=()=>form();
  $$('[data-edit]').forEach(b=>b.onclick=()=>form(menu.find(m=>m.id===Number(b.dataset.edit))));
}

async function ownerBilling(){
  tables=await api('/api/tables');
  const q=Number(new URLSearchParams(location.search).get('table'));
  const qs=Number(new URLSearchParams(location.search).get('session'));
  const occupiedTables = tables.filter(t=>t.occupied);
  
  $('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">Counter & payments</div><h1>Billing counter</h1><div class="muted small">Select any table or active pickup order to settle bills and add counter items.</div></div><a class="btn" href="/owner/payments.html">View all payments →</a></div><div class="panel"><div class="panel-head"><h2>Active sessions & tables</h2><span class="pill">${occupiedTables.length} active</span></div><div class="field" style="max-width:430px"><label>Select bill target</label><select id="bill-table"><option value="">Choose a table or pickup order…</option>${occupiedTables.map(t=>`<option value="${t.id}" ${q===t.id||(qs&&t.sessionId===qs)?'selected':''}>${t.isPickup?'🛍️ [PICKUP] ':''}${esc(t.name)} · ${money(t.estimatedTotal)}</option>`).join('')}</select></div><div id="bill-detail"><div class="empty">Choose an active table or pickup order to view and tweak its consolidated bill.</div></div></div>`;
  
  $('#bill-table').onchange = () => {
    const selId = $('#bill-table').value;
    const item = tables.find(x => x.id === Number(selId));
    if (item && item.isPickup && item.sessionId) loadBillSession(item.sessionId);
    else loadBill(selId);
  };
  
  if(q&&tables.some(t=>t.id===q&&t.occupied)){
    const item = tables.find(t=>t.id===q);
    if(item?.isPickup && item.sessionId) loadBillSession(item.sessionId);
    else loadBill(q);
  } else if(qs) loadBillSession(qs);
}

async function loadBillSession(sessionId){ loadBillByIdOrSession({sessionId}); }
async function loadBill(tableId){ loadBillByIdOrSession({tableId}); }

async function loadBillByIdOrSession({tableId, sessionId}){
  try {
    let endpoint = tableId ? `/api/bill/${tableId}` : `/api/bill/session/${sessionId}`;
    const b = await api(endpoint);
    sessionData = b;
    const isPickup = b.table_name === 'Pickup Orders';
    
    $('#bill-detail').innerHTML=`
      <div class="panel-head" style="margin-top:15px">
        <div><h2>${isPickup?'🛍️ Pickup Order · ':''}${esc(b.table_name)} · Session #${b.id}</h2><div class="muted small">${b.orders.length} order(s) · Invoice ${esc(b.bill.invoice_no)}</div></div>
        ${statusPill(b.bill.status)}
      </div>
      <div class="table-wrap">
        <table>
          <thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Line total</th></tr></thead>
          <tbody>${b.items.map(i=>`<tr><td><strong>${esc(i.item_name)}</strong>${i.notes?`<div class="muted small">${esc(i.notes)}</div>`:''}</td><td>${i.quantity}</td><td>${money(i.unit_price)}</td><td>${money(i.unit_price*i.quantity)}</td></tr>`).join('')}</tbody>
        </table>
      </div>
      
      <!-- ADD EXTRA ITEM AT BILLING COUNTER (e.g. water bottle, soft drink) -->
      <div style="background:#f6f9f6;padding:12px;border-radius:10px;margin:15px 0;border:1px dashed #c2d5c8">
        <strong>＋ Add counter item (Water bottle, Soft drink, etc.)</strong>
        <div style="display:flex;gap:10px;margin-top:8px;flex-wrap:wrap">
          <select id="extra-menu-item" style="flex:2;padding:9px;border:1px solid #dce4dc;border-radius:8px"><option value="">Select menu item…</option></select>
          <input id="extra-qty" type="number" min="1" value="1" style="width:70px;padding:9px;border:1px solid #dce4dc;border-radius:8px">
          <button class="btn btn-sm btn-primary" id="add-extra-btn">Add to bill</button>
        </div>
      </div>

      <div style="max-width:430px;margin:20px 0 0 auto">
        <div class="status-metric"><span>Subtotal</span><strong>${money(b.bill.subtotal)}</strong></div>
        <div class="status-metric"><span>GST (${b.bill.tax_rate}%)</span><strong>${money(b.bill.tax_amount)}</strong></div>
        <div class="status-metric"><span>Grand total</span><strong>${money(b.bill.total)}</strong></div>
        <div class="status-metric"><span>Paid so far</span><strong>${money(b.bill.paid_amount)}</strong></div>
        <div class="status-metric"><span>Balance due</span><strong>${money(b.bill.total-b.bill.paid_amount)}</strong></div>
      </div>
      ${b.bill.status!=='paid'&&b.bill.total>b.bill.paid_amount?`<div class="panel" style="max-width:430px;margin:18px 0 0 auto;text-align:center"><strong>Scan to pay ${money(b.bill.total-b.bill.paid_amount)}</strong><div id="bill-payment-qr-status" class="muted small" style="margin:8px 0">Loading payment QR code…</div><img id="bill-payment-qr" alt="Payment QR code for ${money(b.bill.total-b.bill.paid_amount)}" style="display:none;width:200px;height:200px;margin:0 auto"></div>`:''}

      <div class="panel-head" style="margin-top:20px">
        <h2>Customer & payment details</h2>
        <button class="btn btn-sm" id="print-receipt">Print receipt</button>
      </div>

      <div class="form-grid">
        <div class="field"><label>Customer name</label><input id="bill-customer-name" value="${esc(b.orders[0]?.customer_name||'')}" required placeholder="Customer name"></div>
        <div class="field"><label>Phone number</label><input id="bill-customer-phone" type="tel" value="${esc(b.orders[0]?.customer_phone||'')}" required placeholder="9876543210"></div>
        <div class="field"><label>Amount received (₹)</label><input id="payment-amount" type="number" min="0.01" step="0.01" max="${(b.bill.total-b.bill.paid_amount).toFixed(2)}" value="${(b.bill.total-b.bill.paid_amount).toFixed(2)}"></div>
        <div class="field"><label>Payment method</label><select id="payment-method"><option>Cash</option><option>UPI</option><option>Card</option><option>Other</option></select></div>
      </div>
      <label class="muted small" style="display:flex;gap:8px;align-items:center;margin:10px 0"><input id="customer-marketing-optin" type="checkbox" checked> Customer agrees to receive occasional WhatsApp offers</label>
      
      ${b.bill.status==='paid'?`<div class="notice">This bill is settled. Use Payments to send or resend the e-bill.</div>`:`<button class="btn btn-primary" id="record-payment">Confirm payment</button>`}
    `;

    const qrImage=$('#bill-payment-qr');
    const qrStatus=$('#bill-payment-qr-status');
    if(qrImage)billingQrDataUrl(b.bill.id).then(url=>{qrImage.src=url;qrImage.style.display='block';qrStatus?.remove()}).catch(e=>{if(qrStatus)qrStatus.textContent=`Payment QR unavailable: ${e.message}`});

    // Populate extra menu item dropdown
    const allMenu = await api('/api/menu/manage');
    const sel = $('#extra-menu-item');
    allMenu.forEach(m => {
      const opt = document.createElement('option'); opt.value = m.id; opt.textContent = `${m.name} (${money(m.price)})`; sel.append(opt);
    });

    $('#add-extra-btn').onclick = async () => {
      const menuItemId = $('#extra-menu-item').value; const quantity = $('#extra-qty').value;
      if (!menuItemId) { toast('Select a menu item first.', true); return; }
      try {
        await api(`/api/sessions/${b.id}/items`, { method: 'POST', body: JSON.stringify({ menuItemId: Number(menuItemId), quantity: Number(quantity) }) });
        toast('Item added to bill session.');
        if (tableId) loadBill(tableId); else loadBillSession(b.id);
      } catch(e) { toast(e.message, true); }
    };

    $('#record-payment')?.addEventListener('click',async()=>{
      let customerName=$('#bill-customer-name').value.trim(), customerPhone=$('#bill-customer-phone').value.trim();
      if(!customerName||!customerPhone){toast('Enter customer name and phone number.',true);return}
      if (/^\d{10}$/.test(customerPhone)) customerPhone = '+91' + customerPhone;
      try{
        const result=await api('/api/payments',{method:'POST',body:JSON.stringify({tableId: tableId || undefined, sessionId: b.id, amount:$('#payment-amount').value, method:$('#payment-method').value, customerName, customerPhone, whatsappOptIn:$('#customer-marketing-optin')?.checked===true})});
        toast(result.status==='paid'?'Payment settled.':'Partial payment recorded.');
        if(result.status==='paid'){
          const setting=await api('/api/owner/settings');
          if(setting.autoSend){
            try{
              const bills=await api('/api/owner/payments');
              const bill=bills.payments.find(x=>x.session_id===result.sessionId);
              if(bill) await api(`/api/owner/bills/${bill.bill_id}/send-ebill`,{method:'POST',body:JSON.stringify({customerName,phone:customerPhone})});
              toast('Payment settled and e-bill sent.');
            }catch(e){toast('Payment settled, but e-bill failed: '+e.message,true)}
          }
        }
        await ownerBilling(); if(result.status==='paid') await ownerDashboard();
      }catch(e){toast(e.message,true)}
    });
    $('#print-receipt').onclick=()=>printReceipt(b);
  }catch(e){$('#bill-detail').innerHTML=`<div class="empty">${esc(e.message)}</div>`}
}

async function ownerPayments(){const data=await api('/api/owner/payments');$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">Collection records</div><h1>Payments & e-bills</h1><div class="muted small">Every generated bill, payment method and e-bill delivery status.</div></div><a class="btn" href="/owner/settings.html">E-bill settings →</a></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Table / Order</th><th>Customer</th><th>Phone</th><th>Total / Paid</th><th>Payment</th><th>E-bill</th><th>Action</th></tr></thead><tbody>${data.payments.map(b=>`<tr><td><strong>${esc(b.invoice_no)}</strong><div class="muted small">${esc(b.created_at)}</div></td><td>${esc(b.table_name)}</td><td>${esc(b.customer_name||'—')}</td><td>${esc(b.customer_phone||'—')}</td><td>${money(b.total)}<div class="muted small">Paid ${money(b.paid_amount)}</div></td><td>${esc(b.methods||'—')}</td><td>${b.ebill_sent_at?'<span class="pill green">Sent</span>':'<span class="pill orange">Not sent</span>'}</td><td>${b.status!=='paid'?`<a class="btn btn-sm" href="/owner/billing.html?session=${b.session_id}">Collect payment</a> `:''}<button class="btn btn-sm btn-primary" data-send-ebill="${b.bill_id}" data-name="${esc(b.customer_name||'')}" data-phone="${esc(b.customer_phone||'') }" ${b.status!=='paid'?'disabled':''}>Send e-bill</button></td></tr>`).join('')||'<tr><td colspan="8">No payment bills yet.</td></tr>'}</tbody></table></div></div>`;$$('[data-send-ebill]').forEach(btn=>btn.onclick=async()=>{let name=btn.dataset.name,phone=btn.dataset.phone;if(!name)name=prompt('Customer name?')||'';if(!phone)phone=prompt('Customer WhatsApp number?')||'';if(!phone)return;if(/^\d{10}$/.test(phone))phone='+91'+phone;btn.disabled=true;try{const out=await api(`/api/owner/bills/${btn.dataset.sendEbill}/send-ebill`,{method:'POST',body:JSON.stringify({customerName:name,phone})});toast(out.message);await ownerPayments()}catch(e){toast(e.message,true);btn.disabled=false}})}
async function ownerSettings(){const s=await api('/api/owner/settings');$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">Preferences</div><h1>Restaurant settings</h1><div class="muted small">Configure owner-controlled e-bill delivery behavior.</div></div></div><section class="panel"><div class="panel-head"><div><h2>Automatic WhatsApp e-bill</h2><div class="muted small">When enabled, paid bills are sent automatically to the customer phone number entered at billing.</div></div><span class="pill ${s.whatsappConfigured?'green':'orange'}">${s.whatsappConfigured?'WhatsApp API configured':'WhatsApp API not configured'}</span></div><label style="display:flex;align-items:center;gap:12px;margin:20px 0"><input id="auto-ebill" type="checkbox" ${s.autoSend?'checked':''}> <strong>Auto-send e-bill after successful payment</strong></label><button class="btn btn-primary" id="save-owner-settings">Save settings</button><p class="muted small">If disabled, the owner sends bills manually from Billing or Payments. WhatsApp Cloud API credentials are required for automated delivery.</p></section>`;$('#save-owner-settings').onclick=async()=>{try{await api('/api/owner/settings',{method:'PUT',body:JSON.stringify({autoSend:$('#auto-ebill').checked})});toast('Settings saved.');await ownerSettings()}catch(e){toast(e.message,true)}}}
async function printReceipt(b){const w=window.open('','_blank');if(!w){toast('Allow pop-ups to print the bill.',true);return}let qr='';const balance=Number(b.bill.total)-Number(b.bill.paid_amount);if(balance>0&&b.bill.status!=='paid'){try{const qrUrl=await billingQrDataUrl(b.bill.id);qr=`<div class="payment-qr"><strong>Scan to pay ${money(balance)}</strong><img src="${qrUrl}" alt="Payment QR code for ${money(balance)}"></div>`}catch(e){qr=`<p class="qr-error">Payment QR unavailable: ${esc(e.message)}</p>`}}const rows=b.items.map(i=>`<div class="receipt-line"><span>${esc(i.quantity)} × ${esc(i.item_name)}</span><span>${money(i.unit_price*i.quantity)}</span></div>`).join('');w.document.write(`<html><head><title>Receipt ${esc(b.bill.invoice_no)}</title><style>body{font:13px monospace;padding:22px;max-width:420px;margin:auto}.receipt-line{display:flex;justify-content:space-between;gap:12px;margin:9px 0}hr{border:0;border-top:1px dashed #888}h2{text-align:center}.payment-qr{text-align:center;margin:20px 0}.payment-qr img{display:block;width:200px;height:200px;margin:8px auto}.qr-error{color:#a00;text-align:center}</style></head><body><h2>${esc(config.restaurant)}</h2><p style="text-align:center">${esc(b.table_name)} · ${esc(b.bill.invoice_no)}</p><hr>${rows}<hr><div class="receipt-line"><span>Subtotal</span><b>${money(b.bill.subtotal)}</b></div><div class="receipt-line"><span>GST ${b.bill.tax_rate}%</span><b>${money(b.bill.tax_amount)}</b></div><div class="receipt-line"><strong>Total</strong><strong>${money(b.bill.total)}</strong></div><div class="receipt-line"><span>Paid</span><b>${money(b.bill.paid_amount)}</b></div><div class="receipt-line"><span>Balance due</span><b>${money(balance)}</b></div>${qr}<p style="text-align:center;margin-top:25px">Thank you. Visit again!</p><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
async function ownerReports(){const r=await api('/api/reports');$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">Business intelligence</div><h1>Reports & collections</h1><div class="muted small">Recorded payments and outstanding balances are shown separately.</div></div><button class="btn" id="export-report">↓ Export CSV</button></div><div class="stats">${stat('Recorded collections',money(r.paid),'From payment records','₹')}${stat('Outstanding balance',money(r.pending),'Across generated bills','◷')}${stat('Orders recorded',r.ordersCount,'All order statuses','≋')}${stat('Invoices',r.bills.length,'Generated table bills','▤')}</div><div class="grid-2"><div class="panel"><div class="panel-head"><h2>Recent bills</h2></div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Total</th><th>Paid</th><th>Status</th></tr></thead><tbody>${r.bills.map(b=>`<tr><td>${esc(b.invoice_no)}</td><td>${money(b.total)}</td><td>${money(b.paid_amount)}</td><td>${statusPill(b.status)}</td></tr>`).join('')||'<tr><td colspan="4">No bills generated yet.</td></tr>'}</tbody></table></div></div><div class="panel"><div class="panel-head"><h2>Popular dishes</h2></div>${r.topItems.map((x,i)=>`<div class="status-metric"><span>${i+1}. ${esc(x.item_name)}</span><strong>${x.quantity} sold</strong></div>`).join('')||'<div class="empty">Orders will appear here after the first sale.</div>'}<div class="panel-head" style="margin-top:20px"><h2>Payment methods</h2></div>${r.byMethod.map(x=>`<div class="status-metric"><span>${esc(x.method)}</span><strong>${money(x.amount)}</strong></div>`).join('')||'<div class="muted small">No payments recorded yet.</div>'}</div></div>`;$('#export-report').onclick=()=>{const rows=[['invoice_no','total','paid_amount','status','created_at'],...r.bills.map(b=>[b.invoice_no,b.total,b.paid_amount,b.status,b.created_at])];const csv=rows.map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='restaurant-bills.csv';a.click();URL.revokeObjectURL(a.href)}}
async function initWaiter(){if(page==='dashboard')await waiterDashboard();if(page==='order')await waiterOrder();if(page==='tables')await waiterTables();if(page==='ready')await waiterReady()}
async function waiterDashboard(){tables=await api('/api/tables');orders=await api('/api/orders');const active=orders.filter(o=>!['served','cancelled'].includes(o.status));const ready=orders.filter(o=>o.status==='ready');$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">Floor operations</div><h1>Service overview</h1><div class="muted small">Create orders, receive kitchen-ready alerts, and confirm delivery to the correct table.</div></div><div class="topbar-left"><label class="muted small" style="display:flex;align-items:center;gap:8px"><input class="waiter-sound-toggle" type="checkbox" ${waiterSoundEnabled?'checked':''}> Ready order sound</label><a href="/waiter/ready.html" class="btn ${ready.length?'btn-primary':''}">🔔 Ready to serve ${ready.length?`(${ready.length})`:''}</a><a href="/waiter/order.html" class="btn btn-primary">＋ Create order</a></div></div><div class="stats">${stat('Tables occupied',tables.filter(t=>!t.isPickup&&t.occupied).length,`${tables.length} active tables`,'▦')}${stat('Active tickets',active.length,'Not yet served','≋')}${stat('Ready to serve',ready.length,'Pick up from kitchen','🔔')}${stat('New tickets',orders.filter(o=>o.status==='new').length,'Just submitted','◷')}</div><div class="panel"><div class="panel-head"><div><h2>🔔 Kitchen hand-off queue</h2><div class="muted small">Orders marked Ready by the kitchen need a waiter to deliver them.</div></div><a class="btn btn-sm" href="/waiter/ready.html">Open queue →</a></div>${ready.length?`<div class="ticket-grid">${ready.slice(0,4).map(waiterReadyCard).join('')}</div>`:'<div class="empty">No food waiting for pickup. Ready orders will appear here instantly.</div>'}</div><div class="panel"><div class="panel-head"><h2>Floor table status</h2><a class="btn btn-sm" href="/waiter/tables.html">View sessions →</a></div><div class="table-grid">${tables.filter(t=>!t.isPickup).map(tableCard).join('')}</div></div>`;bindWaiterSoundToggle();bindWaiterServeActions()}
async function waiterReady(){orders=await api('/api/orders?status=ready');const ready=orders.filter(o=>o.status==='ready');$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">Service hand-off</div><h1>Ready to serve</h1><div class="muted small">When the kitchen marks an order Ready, it appears here. Pick up every item, deliver it to the named table, then mark the order Served.</div></div><div class="topbar-left"><label class="muted small" style="display:flex;align-items:center;gap:8px"><input class="waiter-sound-toggle" type="checkbox" ${waiterSoundEnabled?'checked':''}> Ready order sound</label><span class="pill ${ready.length?'orange':'green'}">${ready.length} waiting</span></div></div><div class="panel"><div class="panel-head"><h2>Kitchen pickup notifications</h2><span class="muted small">Live queue · newest first</span></div>${ready.length?`<div class="ticket-grid">${ready.map(waiterReadyCard).join('')}</div>`:'<div class="empty">All caught up! No orders are waiting for delivery. Keep this page open for live kitchen notifications.</div>'}</div>`;bindWaiterSoundToggle();bindWaiterServeActions()}
function bindWaiterSoundToggle(){$$('.waiter-sound-toggle').forEach(toggle=>toggle.onchange=()=>{waiterSoundEnabled=toggle.checked;try{localStorage.setItem(waiterSoundPreferenceKey,waiterSoundEnabled?'on':'off')}catch(error){console.error('Could not save waiter sound preference.',error);toast('Could not save the sound preference on this device.',true)}})}
function playWaiterNotification(){if(!waiterSoundEnabled)return;kitchenNotificationAudio.currentTime=0;kitchenNotificationAudio.play().catch(error=>{if(error.name==='NotAllowedError'){if(!waiterSoundPlaybackWarningShown){toast('Browser blocked notification sound. Interact with the page to enable audio.',true);waiterSoundPlaybackWarningShown=true}}else console.error('Could not play waiter notification sound.',error)})}
function waiterReadyCard(o){return `<article class="ticket ready waiter-ready-ticket"><div class="ticket-head"><div><div class="eyebrow">Pickup · Ticket #${o.id}</div><h3>${o.order_type==='pickup'?`Pickup · ${esc(o.customer_name||'Guest')}`:`Deliver to ${esc(o.table_name)}`}</h3><div class="muted small">${new Date(o.created_at+'Z').toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})} · ${esc(o.source)} order</div></div><span class="pill orange">🔔 Ready for pickup</span></div><div class="ticket-items">${o.items.map(i=>`<div class="ticket-item"><span><strong>${i.quantity} × ${esc(i.item_name)}</strong>${i.notes?`<div class="muted small">${esc(i.notes)}</div>`:''}</span></div>`).join('')}</div>${o.customer_note?`<div class="notice">Order note: ${esc(o.customer_note)}</div>`:''}<div class="ticket-actions"><button class="btn btn-primary btn-sm" data-waiter-serve="${o.id}">✓ ${o.order_type==='pickup'?'Handed to pickup customer':`Delivered to ${esc(o.table_name)}`}</button></div></article>`}
function bindWaiterServeActions(){$$('[data-waiter-serve]').forEach(b=>b.onclick=async()=>{const id=b.dataset.waiterServe;const original=b.textContent;b.disabled=true;b.textContent='Confirming delivery…';try{await api(`/api/orders/${id}/status`,{method:'PATCH',body:JSON.stringify({status:'served'})});toast(`Order #${id} marked served.`);await waiterReady()}catch(e){toast(e.message,true);b.disabled=false;b.textContent=original}})}
async function waiterTables(){tables=await api('/api/tables');$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">Table sessions</div><h1>Floor tables</h1><div class="muted small">Select a table to add to its current session or request the bill.</div></div><a class="btn btn-primary" href="/waiter/order.html">＋ New order</a></div><div class="table-grid">${tables.filter(t=>!t.isPickup).map(t=>`<article class="table-card"><div class="table-card-top"><div class="table-number">${esc(t.name)}</div>${t.occupied?'<span class="pill orange">Occupied</span>':'<span class="pill green">Available</span>'}</div><div class="muted small" style="margin-top:8px">Capacity ${t.capacity} · ${t.orderCount} order(s)</div><div class="amount">${money(t.estimatedTotal)}</div><div class="muted small">Estimated current session total</div><div class="table-card-foot"><a class="btn btn-sm" href="/waiter/order.html?table=${t.id}">Add order</a><a class="btn btn-sm" href="/owner/billing.html?table=${t.id}">Request bill</a></div></article>`).join('')}</div>`}
async function waiterOrder(){tables=await api('/api/tables');menu=await api('/api/menu');const q=Number(new URLSearchParams(location.search).get('table'));selectedTable=q||tables[0]?.id||1;cart={};$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">Staff-assisted ordering</div><h1>Create an order</h1><div class="muted small">Orders placed here join the same table session and consolidated final bill.</div></div></div><div class="panel" style="margin-bottom:18px"><div class="form-grid"><div class="field"><label>Table</label><select id="order-table">${tables.filter(t=>!t.isPickup).map(t=>`<option value="${t.id}" ${t.id===selectedTable?'selected':''}>${esc(t.name)}${t.occupied?' · active session':''}</option>`).join('')}</select></div><div class="field"><label>Special instructions for this order</label><input id="order-note" placeholder="e.g. Serve starters first"></div></div></div><div class="menu-filters" id="menu-filters"></div><div class="food-grid" id="food-grid"></div><div id="cart-summary"></div>`;$('#order-table').onchange=e=>selectedTable=Number(e.target.value);renderOrderMenu();}
function renderOrderMenu(filter='All'){const categories=['All',...new Set(menu.map(m=>m.category))];$('#menu-filters').innerHTML=categories.map(c=>`<button class="filter-chip ${c===filter?'active':''}" data-filter="${esc(c)}">${esc(c)}</button>`).join('');$$('[data-filter]').forEach(b=>b.onclick=()=>renderOrderMenu(b.dataset.filter));$('#food-grid').innerHTML=menu.filter(m=>filter==='All'||m.category===filter).map(m=>`<article class="food-card"><img class="food-image" src="${esc(m.image)}" alt="${esc(m.name)}" loading="lazy" onerror="this.src='https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=900&q=80'"><div class="food-body"><div class="food-top"><h3 class="food-name">${esc(m.name)}</h3><span class="food-price">${money(m.price)}</span></div><div class="food-desc">${esc(m.description)}</div><div class="food-actions"><span class="muted small">${esc(m.category)}</span><div class="qty-control"><button data-minus="${m.id}">−</button><strong>${cart[m.id]?.qty||0}</strong><button data-plus="${m.id}">＋</button></div></div></div></article>`).join('');$$('[data-plus]').forEach(b=>b.onclick=()=>{const m=menu.find(x=>x.id===Number(b.dataset.plus));cart[m.id]??={item:m,qty:0};cart[m.id].qty++;renderOrderMenu(filter)});$$('[data-minus]').forEach(b=>b.onclick=()=>{const id=b.dataset.minus;if(cart[id])cart[id].qty=Math.max(0,cart[id].qty-1);renderOrderMenu(filter)});renderCartSummary()}
function renderCartSummary(){const items=Object.values(cart).filter(x=>x.qty>0);const total=items.reduce((s,x)=>s+x.item.price*x.qty,0);$('#cart-summary').innerHTML=items.length?`<div class="cart-bar"><div><strong>${items.reduce((s,x)=>s+x.qty,0)} item(s) · ${money(total)}</strong><div style="font-size:11px;color:#bcd2c7;margin-top:4px">Tax is calculated on the consolidated bill.</div></div><button class="btn" id="send-kitchen">Send order to kitchen →</button></div>`:'';$('#send-kitchen')?.addEventListener('click',async()=>{try{const result=await api('/api/orders',{method:'POST',body:JSON.stringify({tableId:selectedTable,note:$('#order-note')?.value||'',items:items.map(x=>({menuItemId:x.item.id,quantity:x.qty}))})});cart={};toast(`Order #${result.id} sent to kitchen.`);location.href='/waiter/tables.html'}catch(e){toast(e.message,true)}})}
async function initKitchen(){if(page==='kitchen')await kitchenBoard();if(page==='history')await kitchenHistory()}
async function kitchenBoard(){orders=await api('/api/orders');const incoming=orders.filter(o=>!knownKitchenOrderIds.has(Number(o.id))&&o.status==='new');orders.forEach(o=>knownKitchenOrderIds.add(Number(o.id)));if(kitchenInitialOrdersLoaded&&incoming.length)playKitchenNotification();kitchenInitialOrdersLoaded=true;const active=orders.filter(o=>!['served','cancelled'].includes(o.status));$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">Kitchen display system</div><h1>Kitchen tickets</h1><div class="muted small">New tickets appear live. Use the status controls as each order progresses.</div></div><div class="topbar-left"><label class="muted small" style="display:flex;align-items:center;gap:8px"><input id="kitchen-sound-toggle" type="checkbox" ${kitchenSoundEnabled?'checked':''}> New order sound</label><a class="btn" href="/kitchen/history.html">Completed tickets →</a></div></div><div class="stats">${stat('New',active.filter(o=>o.status==='new').length,'Awaiting preparation','◷')}${stat('Preparing',active.filter(o=>o.status==='preparing').length,'In progress','♨')}${stat('Ready',active.filter(o=>o.status==='ready').length,'Ready for pickup','✓')}${stat('Active tickets',active.length,'Across all tables','▤')}</div><div class="ticket-grid">${active.map(ticketCard).join('')||'<div class="empty" style="grid-column:1/-1">No active kitchen tickets. New orders will appear here automatically.</div>'}</div>`;$('#kitchen-sound-toggle').onchange=e=>{kitchenSoundEnabled=e.target.checked;try{localStorage.setItem(kitchenSoundPreferenceKey,kitchenSoundEnabled?'on':'off')}catch(error){console.error('Could not save kitchen sound preference.',error);toast('Could not save the sound preference on this device.',true)}}}
function playKitchenNotification(){if(!kitchenSoundEnabled)return;kitchenNotificationAudio.currentTime=0;kitchenNotificationAudio.play().catch(error=>{if(error.name==='NotAllowedError'){if(!kitchenSoundPlaybackWarningShown){toast('Browser blocked notification sound. Interact with the page to enable audio.',true);kitchenSoundPlaybackWarningShown=true}}else console.error('Could not play kitchen notification sound.',error)})}
function ticketCard(o){const status=o.status;const next=status==='new'?'preparing':'ready';const label=status==='new'?'Start preparing':'Mark ready for waiter pickup';return `<article class="ticket ${esc(status)}"><div class="ticket-head"><div><div class="eyebrow">Ticket #${o.id}</div><h3>${o.order_type==='pickup'?`Pickup · ${esc(o.customer_name||'Guest')}`:esc(o.table_name)}</h3><div class="muted small">${new Date(o.created_at+'Z').toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})} · ${esc(o.source)} order</div></div>${statusPill(status)}</div><div class="ticket-items">${o.items.map(i=>`<div class="ticket-item"><span><strong>${i.quantity} × ${esc(i.item_name)}</strong>${i.notes?`<div class="muted small">${esc(i.notes)}</div>`:''}</span></div>`).join('')}</div>${o.customer_note?`<div class="notice">${esc(o.customer_note)}</div>`:''}<div class="ticket-actions">${status==='ready'?'<span class="pill orange">Waiting for waiter pickup</span>':(['served','cancelled'].includes(status)?'':`<button class="btn btn-primary btn-sm" data-status-id="${o.id}" data-next="${next}">${label}</button>`)}</div></article>`}
function bindKitchenActions(){ $$('[data-status-id]').forEach(b=>b.onclick=async()=>{try{await api(`/api/orders/${b.dataset.statusId}/status`,{method:'PATCH',body:JSON.stringify({status:b.dataset.next})});toast(`Ticket moved to ${b.dataset.next}.`);await kitchenBoard()}catch(e){toast(e.message,true)}})}
async function kitchenHistory(){orders=await api('/api/orders');const done=orders.filter(o=>['served','cancelled'].includes(o.status));$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">Kitchen history</div><h1>Completed tickets</h1><div class="muted small">Recently served or cancelled orders.</div></div><a class="btn" href="/kitchen/index.html">← Live kitchen</a></div><div class="ticket-grid">${done.map(ticketCard).join('')||'<div class="empty" style="grid-column:1/-1">No completed tickets yet.</div>'}</div>`}
async function initCustomer(){if(page==='menu')await customerMenu();if(page==='status')await customerStatus();if(page==='review')await customerReview()}
async function customerMenu(reload=true){selectedTable=Number(new URLSearchParams(location.search).get('table'))||selectedTable;const completedAt=Number(sessionStorage.getItem('restaurantos:payment-complete-at')||0);if(completedAt&&Date.now()-completedAt<30*60*1000){location.replace('/review/index.html?table='+selectedTable+'&session='+(sessionStorage.getItem('restaurantos:paid-session')||''));return}const data=await api(`/api/table-session/${selectedTable}`);menu=data.menu;sessionData=data.session;const body=$('#customer-content')||$('#content');body.innerHTML=`<header class="customer-header"><div class="customer-brand"><span class="brand-mark">R</span><span>${esc(config.restaurant)}<div class="muted small" style="font-weight:500;font-family:'DM Sans'">Digital menu & ordering</div></span></div><a class="btn" href="/customer/status.html?table=${selectedTable}">Track order ↗</a></header><section class="customer-hero"><div><div class="eyebrow" style="color:#a7d8bd">TABLE ${esc(data.table.name.toUpperCase())}</div><h1>Good food, <br>just a few taps away.</h1><p>Explore our kitchen favourites, add them to your basket and follow your order as it is prepared.</p></div><div class="hero-badge">● Open for ordering<br><span style="color:#bcd2c7;display:inline-block;margin-top:6px">Table ${esc(data.table.name)}</span></div></section><div class="page-head"><div><h1 style="font-size:25px">The menu</h1><div class="muted small">Freshly prepared. Made to order.</div></div></div><div class="menu-filters" id="customer-filters"></div><div class="food-grid" id="customer-food"></div><div id="customer-cart"></div>`;renderCustomerMenu();}
function renderCustomerMenu(filter='All'){const cats=['All',...new Set(menu.map(m=>m.category))];$('#customer-filters').innerHTML=cats.map(c=>`<button class="filter-chip ${c===filter?'active':''}" data-cfilter="${esc(c)}">${esc(c)}</button>`).join('');$$('[data-cfilter]').forEach(b=>b.onclick=()=>renderCustomerMenu(b.dataset.cfilter));$('#customer-food').innerHTML=menu.filter(m=>filter==='All'||m.category===filter).map(m=>`<article class="food-card"><img class="food-image" src="${esc(m.image)}" alt="${esc(m.name)}" loading="lazy" onerror="this.src='https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=900&q=80'"><div class="food-body"><div class="food-top"><h3 class="food-name">${esc(m.name)}</h3><span class="food-price">${money(m.price)}</span></div><div class="food-desc">${esc(m.description)}</div><div class="food-actions"><span class="muted small">${esc(m.category)}</span><div class="qty-control"><button data-cminus="${m.id}">−</button><strong>${cart[m.id]?.qty||0}</strong><button data-cplus="${m.id}">＋</button></div></div></div></article>`).join('');$$('[data-cplus]').forEach(b=>b.onclick=()=>{const m=menu.find(x=>x.id===Number(b.dataset.cplus));cart[m.id]??={item:m,qty:0};cart[m.id].qty++;renderCustomerMenu(filter)});$$('[data-cminus]').forEach(b=>b.onclick=()=>{if(cart[b.dataset.cminus])cart[b.dataset.cminus].qty=Math.max(0,cart[b.dataset.cminus].qty-1);renderCustomerMenu(filter)});const items=Object.values(cart).filter(x=>x.qty>0);const subtotal=items.reduce((s,x)=>s+x.item.price*x.qty,0);const estimate=subtotal*(1+(Number(config.taxRate)||0)/100);$('#customer-cart').innerHTML=items.length?`<div class="cart-bar"><div><strong>${items.reduce((s,x)=>s+x.qty,0)} item(s) · ${money(estimate)}</strong><div style="font-size:11px;color:#bcd2c7;margin-top:4px">Estimated with ${config.taxRate}% tax. Final total is confirmed at the counter.</div></div><button class="btn" id="place-customer-order">Place order →</button></div>`:'';$('#place-customer-order')?.addEventListener('click',async()=>{try{const result=await api('/api/orders',{method:'POST',body:JSON.stringify({tableId:selectedTable,items:items.map(x=>({menuItemId:x.item.id,quantity:x.qty}))})});cart={};toast('Order sent to the kitchen.');location.href=`/customer/status.html?table=${selectedTable}&order=${result.id}`}catch(e){toast(e.message,true)}})}
async function customerStatus(){selectedTable=Number(new URLSearchParams(location.search).get('table'))||1;const params=new URLSearchParams(location.search);const orderId=Number(params.get('order')||0);if(orderId){try{const state=await api(`/api/customer-order/${orderId}`);if(state.paid){redirectToReview(state.tableId,state.sessionId);return}}catch(e){console.debug('Could not resolve customer payment state',e)}}const data=await api(`/api/table-session/${selectedTable}`);sessionData=data.session;const body=$('#customer-content')||$('#content');if(!sessionData){body.innerHTML=`<header class="customer-header"><div class="customer-brand">${esc(config.restaurant)}</div><a class="btn" href="/customer/menu.html?table=${selectedTable}">Back to menu</a></header><div class="panel"><div class="empty">No active order for this table yet. Browse the menu to get started.</div><a class="btn btn-primary" style="margin-top:14px" href="/customer/menu.html?table=${selectedTable}">Browse menu</a></div>`;return}const items=sessionData.items||[];const eta=sessionData.orders.some(o=>o.status==='new')?'5–10 min':sessionData.orders.some(o=>o.status==='preparing')?'10–15 min':sessionData.orders.some(o=>o.status==='ready')?'Ready now':'Served';body.innerHTML=`<header class="customer-header"><div class="customer-brand"><span class="brand-mark">R</span><span>${esc(config.restaurant)}<div class="muted small" style="font-weight:500;font-family:'DM Sans'">Live order status</div></span></div><a class="btn" href="/customer/menu.html?table=${selectedTable}">＋ Add more</a></header><section class="customer-hero"><div><div class="eyebrow" style="color:#a7d8bd">TABLE ${esc(sessionData.table_name.toUpperCase())}</div><h1>Your order is<br>in good hands.</h1><p>Kitchen updates refresh live on this page. You can add another order to the same table session.</p></div><div class="hero-badge">Estimated total<br><strong style="display:inline-block;font-size:20px;margin-top:6px;color:white">${money(sessionData.total)}</strong><div style="margin-top:8px;color:#bcd2c7">Estimated wait: ${eta}</div></div></section><div class="grid-2"><div class="panel"><div class="panel-head"><h2>Order progress</h2><span class="pill green">Live</span></div>${sessionData.orders.map(o=>`<div style="padding:12px 0;border-bottom:1px solid var(--line)"><div style="display:flex;justify-content:space-between;gap:10px"><strong>Order #${o.id}</strong>${statusPill(o.status)}</div><div class="muted small" style="margin-top:7px">${o.items.map(i=>`${i.quantity} × ${esc(i.item_name)}`).join(' · ')}</div></div>`).join('')}<div class="status-step"><span class="step-icon">✓</span><div><strong>Order received</strong><div class="muted small">The kitchen has your order.</div></div></div><div class="status-step"><span class="step-icon">♨</span><div><strong>Preparing your food</strong><div class="muted small">Status changes are shown above.</div></div></div><div class="status-step"><span class="step-icon">✓</span><div><strong>Ready to serve</strong><div class="muted small">A team member will bring it to your table.</div></div></div></div><div class="panel"><div class="panel-head"><h2>Estimated bill</h2></div>${items.map(i=>`<div class="status-metric"><span>${i.quantity} × ${esc(i.item_name)}</span><strong>${money(i.quantity*i.unit_price)}</strong></div>`).join('')}<div class="status-metric"><span>Subtotal</span><strong>${money(sessionData.subtotal)}</strong></div><div class="status-metric"><span>Estimated tax (${sessionData.tax_rate}%)</span><strong>${money(sessionData.tax)}</strong></div><div class="status-metric"><strong>Estimated total</strong><strong style="font-size:18px;color:var(--brand)">${money(sessionData.total)}</strong></div><p class="muted small">Final bill is generated by the cashier after your table session is ready to close.</p><a href="/customer/menu.html?table=${selectedTable}" class="btn btn-primary" style="width:100%">Add another order</a></div></div>`}
function redirectToReview(tableId,sessionId){
  sessionStorage.setItem('restaurantos:payment-complete-at',String(Date.now()));
  sessionStorage.setItem('restaurantos:paid-session',String(sessionId||''));
  location.replace(`/review/index.html?table=${encodeURIComponent(tableId)}&session=${encodeURIComponent(sessionId||'')}`);
}
async function customerReview(){const params=new URLSearchParams(location.search),tableId=Number(params.get('table'))||1;const root=$('#review-content')||$('#content');const reviewUrl=location.href;history.replaceState({restaurantOSReview:true},'',reviewUrl);history.pushState({restaurantOSReview:true},'',reviewUrl);window.onpopstate=()=>history.pushState({restaurantOSReview:true},'',reviewUrl);root.innerHTML=`<main class="review-page"><div class="review-glow"></div><header class="review-top"><div class="review-brand"><span class="review-mark">R</span><span>${esc(config.restaurant)}<small>Thank you for choosing us</small></span></div><span class="review-chip">✓ Payment complete</span></header><section class="review-card"><div class="review-success"><span>✓</span></div><div class="eyebrow">ORDER COMPLETE · TABLE ${tableId}</div><h1>Thank you for dining with us.</h1><p class="review-intro">Your payment is complete and this ordering session is closed.</p><div class="review-actions"><a class="review-primary" href="${esc(window.RESTAURANT_GOOGLE_REVIEW_URL||'https://www.google.com/search?q='+encodeURIComponent(config.restaurant+' Google reviews'))}" target="_blank" rel="noopener noreferrer">Rate us on Google <span>↗</span></a><p class="review-hint">A quick review helps our team grow.</p></div><div class="review-footer"><span>● Payment completed</span><span>Your e-bill can be sent by the cashier.</span></div></section></main>`}
async function initAdmin(){if(page==='broadcasts'){await adminBroadcasts();return}if(page==='events'){ const s=await api('/api/technical-status');$('#content').innerHTML=`<div class="page-head"><div><div class="eyebrow">Diagnostics</div><h1>System events</h1><div class="muted small">Technical events only; no restaurant business data.</div></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Event</th><th>Timestamp</th></tr></thead><tbody>${s.recentTechnicalEvents.map(e=>`<tr><td>${esc(e.event)}</td><td>${esc(e.at)}</td></tr>`).join('')||'<tr><td colspan="2">No events yet.</td></tr>'}</tbody></table></div></div>`;return}const s=await api('/api/technical-status');$('#content').innerHTML=`<div class="super-banner"><strong>Privacy boundary:</strong> this technical role cannot retrieve restaurant sales, order contents, bills, payment values, customer details or business analytics. The endpoint itself returns only operational diagnostics.</div><div class="page-head"><div><div class="eyebrow">Platform operations</div><h1>Technical health</h1><div class="muted small">Application availability and real-time infrastructure only.</div></div><button class="btn" id="refresh-health">↻ Refresh</button></div><div class="stats">${stat('Application','Online','HTTP server responding','✓')}${stat('Socket clients',s.connectedBrowsers,'Connected browser tabs','⌁')}${stat('Database',s.database,'SQLite connection status','▤')}${stat('Uptime',`${Math.floor(s.uptimeSeconds/60)}m`,'Since last restart','◷')}</div><div class="panel"><div class="panel-head"><h2>System diagnostics</h2><span class="pill green">Operational</span></div><div class="status-metric"><span>Database file size</span><strong>${s.databaseSizeBytes==null?'Unavailable':`${(s.databaseSizeBytes/1024).toFixed(1)} KB`}</strong></div><div class="status-metric"><span>Realtime transport</span><strong>Socket.IO</strong></div><div class="status-metric"><span>Restaurant business data access</span><strong>Blocked by role guard</strong></div><div class="status-metric"><span>Recent technical event count</span><strong>${s.recentTechnicalEvents.length}</strong></div><p class="muted small">This local trial's role selector is intended for trusted local testing, not public deployment. Production needs real authenticated accounts and server-managed sessions.</p></div>`;$('#refresh-health')?.addEventListener('click',()=>initAdmin());}
async function adminBroadcasts(){
 const data=await api('/api/broadcasts');
 $('#content').innerHTML=`<div class="super-banner"><strong>Privacy boundary:</strong> this screen manages campaign copy and delivery status only. It never displays phone numbers, restaurant sales, bills or customer order details.</div><div class="page-head"><div><div class="eyebrow">Customer communications</div><h1>WhatsApp broadcasts</h1><div class="muted small">Create a draft, review the message, then send it to customers who explicitly opted in.</div></div><span class="pill ${data.whatsappConfigured?'green':'orange'}">${data.whatsappConfigured?'WhatsApp connected':'WhatsApp setup needed'}</span></div><div class="stats">${stat('Opted-in audience',data.eligibleAudience,'Customers who gave consent','♧')}${stat('Saved campaigns',data.broadcasts.length,'Drafts and delivery records','▤')}${stat('Delivery provider',data.whatsappConfigured?'Connected':'Not configured','WhatsApp Cloud API','↗')}${stat('Privacy','Opt-in only','No contact list exposed','✓')}</div><div class="grid-2"><section class="panel"><div class="panel-head"><h2>Create a broadcast</h2><span class="pill">Draft first</span></div><form id="broadcast-form"><div class="field"><label for="broadcast-title">Campaign name</label><input id="broadcast-title" required maxlength="100" placeholder="e.g. Weekend specials"></div><div class="field" style="margin-top:14px"><label for="broadcast-message">WhatsApp message</label><textarea id="broadcast-message" required maxlength="3000" rows="7" placeholder="Write a useful update for customers who opted in…"></textarea><div class="muted small">Up to 3,000 characters. Avoid sensitive information.</div></div><div class="ticket-actions" style="margin-top:16px"><button class="btn" type="submit" id="save-broadcast">Save draft</button><button class="btn btn-primary" type="button" id="create-send-broadcast">Create & send</button></div><p class="muted small" id="broadcast-notice" aria-live="polite">${data.whatsappConfigured?'WhatsApp Cloud API is configured.':'To send automatically, configure WHATSAPP_ACCESS_TOKEN and WHATSAPP_PHONE_NUMBER_ID in .env.'}</p></form></section><section class="panel"><div class="panel-head"><h2>Before you send</h2></div><div class="status-metric"><span>Audience rule</span><strong>Explicit WhatsApp opt-in</strong></div><div class="status-metric"><span>Phone number visibility</span><strong>Hidden from this role</strong></div><div class="status-metric"><span>Send behavior</span><strong>One recipient at a time</strong></div><p class="muted small" style="margin-top:14px">Messages are sent through the configured Meta WhatsApp Cloud API. Keep consent records current and honor opt-out requests before sending campaigns.</p></section></div><section class="panel" style="margin-top:18px"><div class="panel-head"><h2>Campaign history</h2><button class="btn btn-sm" id="refresh-broadcasts">↻ Refresh</button></div><div class="table-wrap"><table><thead><tr><th>Campaign</th><th>Status</th><th>Audience reached</th><th>Created</th><th>Action</th></tr></thead><tbody>${data.broadcasts.map(b=>`<tr><td><strong>${esc(b.title)}</strong><div class="muted small">${esc(b.message.slice(0,90))}${b.message.length>90?'…':''}</div></td><td>${statusPill(b.status)}</td><td>${b.sent_count||0} sent · ${b.failed_count||0} failed</td><td>${esc(b.created_at)}</td><td>${b.status==='sent'?'<span class="muted small">Sent</span>':`<button class="btn btn-sm" data-edit-broadcast="${b.id}">Edit draft</button> <button class="btn btn-sm btn-primary" data-send-broadcast="${b.id}">Send</button>`}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">No campaigns yet. Create your first draft above.</div></td></tr>'}</tbody></table></div></section>`;
 $('#broadcast-form').addEventListener('submit',async e=>{e.preventDefault();try{const id=Number($('#broadcast-form').dataset.editId||0);if(id){await api(`/api/broadcasts/${id}`,{method:'PATCH',body:JSON.stringify({title:$('#broadcast-title').value,message:$('#broadcast-message').value})});toast('Broadcast draft updated.')}else{await api('/api/broadcasts',{method:'POST',body:JSON.stringify({title:$('#broadcast-title').value,message:$('#broadcast-message').value,action:'draft'})});toast('Broadcast draft saved.')}await adminBroadcasts()}catch(e){toast(e.message,true)}});
 $('#create-send-broadcast').onclick=async()=>{try{const created=await api('/api/broadcasts',{method:'POST',body:JSON.stringify({title:$('#broadcast-title').value,message:$('#broadcast-message').value,action:'draft'})});if(!created.broadcast?.id)throw new Error('Could not create campaign');if(!data.whatsappConfigured){toast('Draft created. Configure WhatsApp Cloud API before sending.');await adminBroadcasts();return}const result=await api(`/api/broadcasts/${created.broadcast.id}/send`,{method:'POST'});toast(result.message||'Campaign processed.');await adminBroadcasts();}catch(e){toast(e.message,true)}};
 $('#refresh-broadcasts').onclick=()=>adminBroadcasts();
 $$('[data-send-broadcast]').forEach(b=>b.onclick=async()=>{if(!confirm('Send this message to all opted-in customers? This cannot be undone.'))return;b.disabled=true;b.textContent='Sending…';try{const result=await api(`/api/broadcasts/${b.dataset.sendBroadcast}/send`,{method:'POST'});toast(result.message||'Broadcast processed.');await adminBroadcasts()}catch(e){toast(e.message,true);b.disabled=false;b.textContent='Send'}});
 $$('[data-edit-broadcast]').forEach(b=>b.onclick=async()=>{const item=data.broadcasts.find(x=>x.id===Number(b.dataset.editBroadcast));if(!item)return;$('#broadcast-title').value=item.title;$('#broadcast-message').value=item.message;$('#save-broadcast').textContent='Update draft';$('#broadcast-notice').textContent=`Editing draft #${item.id}. Save will create a fresh draft; use Send in campaign history to deliver a saved campaign.`;$('#broadcast-form').dataset.editId=String(item.id);$('#save-broadcast').textContent='Update draft';$('#create-send-broadcast').textContent='Create new & send';window.scrollTo({top:0,behavior:'smooth'})});
}
